window.docContents[117].resolve({"/rules/PL1003/#PL1003-limitations":{"contents":"Classification uses exact constant names and authenticated compiler evidence, not name patterns; a lookalike name gets no special treatment.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1003: Unknown transitive axioms are forbidden","header":"Limitations and unsupported cases","id":"/rules/PL1003/#PL1003-limitations"},"/rules/PL2002/#PL2002-limitations":{"contents":"Executable-only packages are valid Lean projects but unsupported by manifest schema 2.\n\nThe editor never guesses an omitted project scope.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2002: Configuration must classify the complete Lake surface","header":"Limitations and unsupported cases","id":"/rules/PL2002/#PL2002-limitations"},"/rules/PL3001/#PL3001-limitations":{"contents":"This page's example is a diagnostic demonstration: the violating run is INCOMPLETE by design and is not accepted negative evidence. Its corrected counterpart passed a completed positive check.\n\nThe editor does not analyze execution: it reports neither this rule nor a pending notice for it. Only lake lint, axiomGate (including --file) and the build-lint policy target do.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL3001: Execution closure must have no unresolved paths","header":"Limitations and unsupported cases","id":"/rules/PL3001/#PL3001-limitations"}});